static u32 rotr(u32 x,u32 n){return(x>>n)|(x<<(32-n));}static u32 be32(const u8*p){return((u32)p[0]<<24)|((u32)p[1]<<16)|((u32)p[2]<<8)|p[3];}static void put_be32(u8*p,u32 v){p[0]=(u8)(v>>24);p[1]=(u8)(v>>16);p[2]=(u8)(v>>8);p[3]=(u8)v;}
Digest256 sha256(ByteSpan in){u32 h[8]={0x6a09e667u,0xbb67ae85u,0x3c6ef372u,0xa54ff53au,0x510e527fu,0x9b05688cu,0x1f83d9abu,0x5be0cd19u};u64 total=in.size+1+8,padded=(total+63u)&~63ull;Buffer b((size_t)padded,0);if(in.size)std::memcpy(b.data(),in.data,(size_t)in.size);b[(size_t)in.size]=0x80;u64 bits=in.size*8;for(int i=0;i<8;i++)b[(size_t)padded-1-i]=(u8)(bits>>(i*8));for(u64 off=0;off<padded;off+=64){u32 w[64]{};for(int i=0;i<16;i++)w[i]=be32(b.data()+off+i*4);for(int i=16;i<64;i++){u32 s0=rotr(w[i-15],7)^rotr(w[i-15],18)^(w[i-15]>>3);u32 s1=rotr(w[i-2],17)^rotr(w[i-2],19)^(w[i-2]>>10);w[i]=w[i-16]+s0+w[i-7]+s1;}u32 a=h[0],bb=h[1],c=h[2],d=h[3],e=h[4],f=h[5],g=h[6],hh=h[7];for(int i=0;i<64;i++){u32 S1=rotr(e,6)^rotr(e,11)^rotr(e,25),ch=(e&f)^((~e)&g),t1=hh+S1+ch+K[i]+w[i],S0=rotr(a,2)^rotr(a,13)^rotr(a,22),maj=(a&bb)^(a&c)^(bb&c),t2=S0+maj;hh=g;g=f;f=e;e=d+t1;d=c;c=bb;bb=a;a=t1+t2;}h[0]+=a;h[1]+=bb;h[2]+=c;h[3]+=d;h[4]+=e;h[5]+=f;h[6]+=g;h[7]+=hh;}Digest256 out{};for(int i=0;i<8;i++)put_be32(out.bytes.data()+i*4,h[i]);return out;}
std::string hex(const Digest256&d){static const char H[]="0123456789abcdef";std::string s(64,'0');for(size_t i=0;i<32;i++){s[i*2]=H[d.bytes[i]>>4];s[i*2+1]=H[d.bytes[i]&15];}return s;}Status parse_hex_digest(std::string_view s,Digest256*out){if(!out||s.size()!=64)return Status::InvalidArgument;auto v=[](char c)->int{if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return-1;};for(size_t i=0;i<32;i++){int a=v(s[i*2]),b=v(s[i*2+1]);if(a<0||b<0)return Status::InvalidArgument;out->bytes[i]=(u8)((a<<4)|b);}return Status::Ok;}bool digest_equal(const Digest256&a,const Digest256&b){return a==b;}
bool valid_utf8(ByteSpan s){u64 i=0;while(i<s.size){u8 c=s.data[i++];if(c<0x80)continue;int n=0;u32 cp=0,mincp=0;if((c&0xe0)==0xc0){n=1;cp=c&0x1f;mincp=0x80;}else if((c&0xf0)==0xe0){n=2;cp=c&0x0f;mincp=0x800;}else if((c&0xf8)==0xf0){n=3;cp=c&0x07;mincp=0x10000;}else return false;if(i+(u64)n>s.size)return false;for(int j=0;j<n;j++){u8 x=s.data[i++];if((x&0xc0)!=0x80)return false;cp=(cp<<6)|(x&0x3f);}if(cp<mincp||cp>0x10ffff||(cp>=0xd800&&cp<=0xdfff))return false;}return true;}bool valid_semantic_id(std::string_view s){if(s.empty())return false;for(char c:s)if(!((c>='A'&&c<='Z')||(c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='-'||c=='_'||c=='.'||c==':'))return false;return true;}
const char* status_name(Status s){switch(s){case Status::Ok:return"OK";case Status::InvalidArgument:return"INVALID_ARGUMENT";case Status::IOError:return"IO_ERROR";case Status::BadMagic:return"BAD_MAGIC";case Status::BadVersion:return"BAD_VERSION";case Status::BadLength:return"BAD_LENGTH";case Status::BadDigest:return"BAD_DIGEST";case Status::BadFieldOrder:return"BAD_FIELD_ORDER";case Status::DuplicateField:return"DUPLICATE_FIELD";case Status::UnknownCriticalField:return"UNKNOWN_CRITICAL_FIELD";case Status::InvalidUtf8:return"INVALID_UTF8";case Status::ObjectNotFound:return"OBJECT_NOT_FOUND";case Status::ObjectCollision:return"OBJECT_COLLISION";case Status::LedgerCorrupt:return"LEDGER_CORRUPT";case Status::LedgerSequence:return"LEDGER_SEQUENCE";case Status::LedgerChain:return"LEDGER_CHAIN";case Status::NodeExists:return"NODE_EXISTS";case Status::NodeMissing:return"NODE_MISSING";case Status::BadRevision:return"BAD_REVISION";case Status::EdgeExists:return"EDGE_EXISTS";case Status::EdgeMissing:return"EDGE_MISSING";case Status::ProvenanceMissing:return"PROVENANCE_MISSING";case Status::ScopeMissing:return"SCOPE_MISSING";case Status::ParseError:return"PARSE_ERROR";case Status::DuplicateConflict:return"DUPLICATE_CONFLICT";case Status::EpistemicAmplification:return"EPISTEMIC_AMPLIFICATION";case Status::Unsupported:return"UNSUPPORTED";default:return"INVARIANT_VIOLATION";}}
